-- YG-1359 gerekçeli erteleme ve üst kademeye çıkma; YG-1082 ücret bandı; YG-1556 kurumsal iletişim talebi.
ALTER TABLE is_karti ADD COLUMN ust_rol_ref text REFERENCES rol (kimlik), ADD COLUMN ust_kademe_zamani timestamptz;
CREATE TABLE is_karti_erteleme (kimlik bigserial PRIMARY KEY, is_ref uuid NOT NULL REFERENCES is_karti (kimlik), eski_son timestamptz, yeni_son timestamptz NOT NULL, gerekce text NOT NULL, yapan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), zaman timestamptz NOT NULL DEFAULT now());
CREATE INDEX is_karti_erteleme_is ON is_karti_erteleme (is_ref);
CREATE TABLE ucret_bandi (rol_ref text PRIMARY KEY REFERENCES rol (kimlik), alt_tl numeric(12,2) NOT NULL CHECK (alt_tl > 0), ust_tl numeric(12,2) NOT NULL, giren_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), zaman timestamptz NOT NULL DEFAULT now(), CHECK (ust_tl >= alt_tl));
CREATE TABLE ucret_bandi_yetki (kullanici_ref text PRIMARY KEY REFERENCES kullanici_hesabi (kimlik), veren_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), zaman timestamptz NOT NULL DEFAULT now());
CREATE TABLE ucret_teklifi (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), aday_adi text NOT NULL, rol_ref text NOT NULL REFERENCES rol (kimlik), brut_tl numeric(12,2) NOT NULL CHECK (brut_tl > 0), bant_disi boolean NOT NULL, gerekce text, durum text NOT NULL DEFAULT 'Geçerli' CHECK (durum IN ('Geçerli', 'CEO Onayında', 'Onaylandı', 'Reddedildi')), hazirlayan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), zaman timestamptz NOT NULL DEFAULT now());
CREATE SEQUENCE kurum_talebi_no;
CREATE TABLE kurum_talebi (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), talep_no text NOT NULL UNIQUE, kurum_turu text NOT NULL CHECK (kurum_turu IN ('Sigorta Şirketi', 'Sigorta Brokeri', 'Sigorta Acentesi', 'Kurumsal Müşteri', 'Marina / Tersane / Çekek Sahası', 'Tedarikçi')), kurum_adi text NOT NULL, ad_soyad text NOT NULL, e_posta text NOT NULL, telefon text, mesaj text, adres text, durum text NOT NULL DEFAULT 'Yeni' CHECK (durum IN ('Yeni', 'Yönlendirildi', 'Davet Edildi', 'Kapatıldı')), yonlenen_birim text, not_metni text, isleyen_ref text REFERENCES kullanici_hesabi (kimlik), islem_zamani timestamptz, olusturma_zamani timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON is_karti_erteleme TO yatonet_uygulama; GRANT USAGE ON SEQUENCE is_karti_erteleme_kimlik_seq, kurum_talebi_no TO yatonet_uygulama;
GRANT SELECT, INSERT, UPDATE ON ucret_bandi, ucret_teklifi, kurum_talebi TO yatonet_uygulama; GRANT SELECT, INSERT, DELETE ON ucret_bandi_yetki TO yatonet_uygulama;
